/**
 * @fileoverview Input-blocking overlay utilities for browser automation.
 *
 * While the browser agent performs automated interactive operations (clicks,
 * form fills, key presses, …) a transparent full-viewport overlay is injected
 * that swallows user input events. This prevents a human from interfering with
 * an in-flight automated operation, which could otherwise produce race
 * conditions or corrupt the page state the agent is reasoning about.
 *
 * The overlay is intentionally SUSPENDED (pointer-events disabled) for the
 * duration of the actual automated tool call so that chrome-devtools-mcp's
 * coordinate/element dispatch can reach the real page, then RESUMED afterwards.
 * See {@link buildSuspendInputBlockerScript} / {@link buildResumeInputBlockerScript}.
 *
 * The script strings are passed to chrome-devtools-mcp's evaluate_script tool
 * which expects a plain function expression (NOT an IIFE).
 */

import type { BrowserManager } from './browserManager.js';
import { debugLogger } from '../../utils/debugLogger.js';

/** DOM id of the injected input-blocking overlay element. */
export const INPUT_BLOCKER_ELEMENT_ID = '__gemini_input_blocker';

/**
 * Builds the JavaScript function string that injects the input-blocking
 * overlay.
 *
 * Returns a plain arrow-function expression (no trailing invocation) because
 * chrome-devtools-mcp's evaluate_script tool invokes it internally.
 */
function buildInjectionScript(): string {
  return `() => {
    const id = '${INPUT_BLOCKER_ELEMENT_ID}';
    const existing = document.getElementById(id);
    if (existing) existing.remove();

    const blocker = document.createElement('div');
    blocker.id = id;
    blocker.setAttribute('aria-hidden', 'true');
    blocker.setAttribute('role', 'presentation');

    Object.assign(blocker.style, {
      position: 'fixed',
      top: '0',
      left: '0',
      right: '0',
      bottom: '0',
      zIndex: '2147483646',
      pointerEvents: 'auto',
      cursor: 'not-allowed',
      background: 'transparent',
    });

    // Swallow every interaction so a human cannot interfere with the
    // in-flight automated operation.
    const swallow = (e) => { e.preventDefault(); e.stopPropagation(); };
    [
      'click', 'dblclick', 'mousedown', 'mouseup', 'keydown', 'keyup',
      'keypress', 'wheel', 'touchstart', 'touchmove', 'touchend', 'contextmenu',
    ].forEach((evt) => blocker.addEventListener(evt, swallow, true));

    const label = document.createElement('div');
    label.textContent = 'Gemini CLI is controlling this browser';
    Object.assign(label.style, {
      position: 'fixed',
      bottom: '16px',
      left: '50%',
      transform: 'translateX(-50%)',
      padding: '6px 12px',
      borderRadius: '6px',
      background: 'rgba(66, 133, 244, 0.9)',
      color: '#fff',
      font: '12px sans-serif',
      pointerEvents: 'none',
      whiteSpace: 'nowrap',
    });
    blocker.appendChild(label);

    document.documentElement.appendChild(blocker);
    return 'input-blocker-injected';
  }`;
}

/**
 * Builds the JavaScript function string that removes the input-blocking
 * overlay.
 */
function buildRemovalScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.remove();
    return 'input-blocker-removed';
  }`;
}

/**
 * Builds the JavaScript function string that suspends the input-blocking
 * overlay by disabling its pointer events, so an automated tool call can
 * reach the underlying page.
 */
export function buildSuspendInputBlockerScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.style.pointerEvents = 'none';
    return 'input-blocker-suspended';
  }`;
}

/**
 * Builds the JavaScript function string that resumes the input-blocking
 * overlay by re-enabling its pointer events after an automated tool call.
 */
export function buildResumeInputBlockerScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.style.pointerEvents = 'auto';
    return 'input-blocker-resumed';
  }`;
}

/**
 * Injects the input-blocking overlay into the current page.
 *
 * Never rejects: any failure is logged and swallowed (resolves undefined) so
 * that input-blocker failures never interrupt the automated operation.
 */
export async function injectInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Injecting input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildInjectionScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to inject input blocker:', result);
    } else {
      debugLogger.log('Input blocker injected successfully');
    }
  } catch (error) {
    debugLogger.warn('Error injecting input blocker:', error);
    return undefined;
  }
}

/**
 * Removes the input-blocking overlay from the current page.
 *
 * Never rejects: any failure is logged and swallowed (resolves undefined) so
 * that the overlay is best-effort cleaned up without interrupting callers.
 */
export async function removeInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Removing input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildRemovalScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to remove input blocker:', result);
    } else {
      debugLogger.log('Input blocker removed successfully');
    }
  } catch (error) {
    debugLogger.warn('Error removing input blocker:', error);
    return undefined;
  }
}
